import numpy as np, json, sys
D={n: (np.load('/tmp/w/%s.npy'%n)[:,:,:3].astype(np.int16).mean(axis=2)<160) for n in ['A-101','A-301','A-601','A-602','M-101','E-101','F-101']}

def bands(d, x0,x1,y0,y1):
    sub=d[y0:y1, x0:x1]
    rows=sub.any(axis=1)
    out=[]; s=None
    for i,r in enumerate(rows):
        if r and s is None: s=i
        if (not r) and s is not None: out.append((y0+s,y0+i)); s=None
    if s is not None: out.append((y0+s,y0+len(rows)))
    return out

def glyphs(d, y0,y1,x0,x1):
    sub=d[y0:y1,x0:x1]
    cols=sub.any(axis=0)
    out=[]; s=None
    for i,c in enumerate(cols):
        if c and s is None: s=i
        if (not c) and s is not None: out.append((x0+s,x0+i)); s=None
    if s is not None: out.append((x0+s,x0+len(cols)))
    return out

G={}
def key(a):
    return tuple(a.flatten().tolist())

def extract(d,x0,x1,y0,y1,minh=4,maxh=12):
    res=[]
    for (a,b) in bands(d,x0,x1,y0,y1):
        if b-a<minh or b-a>maxh: continue
        gs=[]
        for (c,e) in glyphs(d,a,b,x0,x1):
            if e-c>10: 
                gs.append(('?',e-c)); continue
            art=d[a:b,c:e]
            k=key(art)
            if k not in G: G[k]=len(G)
            gs.append((G[k],e-c))
        res.append((a,b,gs))
    return res

def text(d,x0,x1,y0,y1,MAP,minh=4,maxh=12):
    lines=[]
    for (a,b,gs) in extract(d,x0,x1,y0,y1,minh,maxh):
        s=''
        for gk,w in gs:
            s += MAP.get(gk,'{%d}'%gk) if not isinstance(gk,str) else gk
        lines.append((a,b,s))
    return lines
