import numpy as np

def rle_rows(d):
    h,w=d.shape
    runs=[]
    for y in range(h):
        row=d[y]
        if not row.any(): runs.append([]); continue
        idx=np.flatnonzero(np.diff(np.concatenate(([0],row.astype(np.int8),[0]))))
        runs.append(list(zip(idx[0::2], idx[1::2])))
    return runs

def cc(d):
    h,w=d.shape
    runs=rle_rows(d)
    parent={}
    def find(a):
        while parent[a]!=a:
            parent[a]=parent[parent[a]]; a=parent[a]
        return a
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[rb]=ra
    labels=[]
    nid=0
    for y in range(h):
        cur=[]
        for (s,e) in runs[y]:
            cur.append((s,e,nid)); parent[nid]=nid; nid+=1
        labels.append(cur)
        if y>0:
            for (s,e,i) in cur:
                for (s2,e2,j) in labels[y-1]:
                    if s2<e and s<e2: union(i,j)
    comps={}
    for y in range(h):
        for (s,e,i) in labels[y]:
            r=find(i)
            if r not in comps: comps[r]=[y,y,s,e,0]
            c=comps[r]; c[0]=min(c[0],y); c[1]=max(c[1],y); c[2]=min(c[2],s); c[3]=max(c[3],e); c[4]+=e-s
    return sorted(comps.values())
