import numpy as np, pickle, collections, sys
from ccl import cc

def gray(n): return np.load('/tmp/w/%s.npy'%n)[:,:,:3].astype(np.int16).mean(axis=2)

def comps(a, th=170):
    d=a<th
    out=[]
    for (y0,y1,x0,x1,size) in cc(d):
        out.append((y0,y1,x0,x1,size))
    return out

def glyphs_of(a, th=170):
    g=[]
    for (y0,y1,x0,x1,size) in comps(a,th):
        h=y1-y0+1; w=x1-x0+1
        if 3<=h<=8 and 1<=w<=9:
            g.append((y0,y1,x0,x1,a[y0:y1+1,x0:x1+1]<th))
    return g

def lines(g, ytol=2, xgap=4):
    # group components into text lines
    g=sorted(g, key=lambda t:(t[0],t[2]))
    used=[False]*len(g); out=[]
    for i,t in enumerate(g):
        if used[i]: continue
        grp=[i]; used[i]=True
        changed=True
        while changed:
            changed=False
            for j,u in enumerate(g):
                if used[j]: continue
                for k in grp:
                    v=g[k]
                    if not (u[1] < v[0]-ytol or u[0] > v[1]+ytol):
                        # y overlap ok; x near
                        if not (u[3] < v[2]-xgap or u[2] > v[3]+xgap):
                            grp.append(j); used[j]=True; changed=True; break
        out.append(sorted([g[k] for k in grp], key=lambda t:t[2]))
    return out
