import numpy as np, collections, pickle, sys
from ccl import cc
from resamp import bilinear

RAMP=' .:-=+*#%@'
def gray(n): return np.load('/tmp/w/%s.npy'%n)[:,:,:3].astype(np.int16).mean(axis=2)

def glyph_comps(a, th=170, hmin=4, hmax=12, wmax=12):
    out=[]
    for (y0,y1,x0,x1,size) in cc(a<th):
        h=y1-y0+1; w=x1-x0+1
        if hmin<=h<=hmax and 1<=w<=wmax: out.append((y0,y1,x0,x1))
    return out

def norm(a,y0,y1,x0,x1,H=12,MW=18):
    crop=(255.0-a[y0:y1+1, x0:x1+1])
    h,w=crop.shape
    W=min(MW,max(1,int(round(H*w/h))))
    r=bilinear(crop,H,W)
    m=r.max()
    if m>0: r=r/m
    return r,W

def group_lines(g, ytol=2, xgap=3):
    g=sorted(g, key=lambda t:(t[0],t[2]))
    used=[False]*len(g); out=[]
    for i in range(len(g)):
        if used[i]: continue
        grp=[i]; used[i]=True
        changed=True
        while changed:
            changed=False
            for j in range(len(g)):
                if used[j]: continue
                u=g[j]
                for k in grp:
                    v=g[k]
                    if not (u[1]<v[0]-ytol or u[0]>v[1]+ytol) and not (u[3]<v[2]-xgap or u[2]>v[3]+xgap):
                        grp.append(j); used[j]=True; changed=True; break
        out.append(sorted([g[k] for k in grp], key=lambda t:t[2]))
    return out

def show_reps(reps, per=8):
    for i0 in range(0,len(reps),per):
        grp=reps[i0:i0+per]
        for r in range(12):
            line=''
            for (g,W) in grp:
                line+=''.join(RAMP[min(9,int(v*9.99))] for v in g[r])+' '*(16-W)+'| '
            print('  '+line)
        print('  '+''.join(('C%-14d'%(i0+i)) for i in range(len(grp))))
        print()
