import numpy as np
def gray(n): return np.load('/tmp/w/%s.npy'%n)[:,:,:3].astype(np.int16).mean(axis=2)
def hlines(d, minlen=25):
    out=[]
    for y in range(d.shape[0]):
        row=d[y]
        if not row.any(): continue
        idx=np.flatnonzero(np.diff(np.concatenate(([0],row.astype(np.int8),[0]))))
        for s,e in zip(idx[0::2], idx[1::2]):
            if e-s>=minlen: out.append((y,s,e))
    return out
def vlines(d, minlen=25):
    out=[]
    for x in range(d.shape[1]):
        col=d[:,x]
        if not col.any(): continue
        idx=np.flatnonzero(np.diff(np.concatenate(([0],col.astype(np.int8),[0]))))
        for s,e in zip(idx[0::2], idx[1::2]):
            if e-s>=minlen: out.append((x,s,e))
    return out
def merge_h(ls, ytol=1):
    ls=sorted(ls)
    out=[]
    for (y,s,e) in ls:
        placed=False
        for i in range(len(out)-1,-1,-1):
            (ys,ss,ee,ys2)=out[i] if len(out[i])==4 else (0,0,0,0)
            if abs(y-ys)<=ytol and not (e<ss-3 or s>ee+3):
                out[i]=(ys,min(s,ss),max(e,ee),max(ys2,y)); placed=True; break
            if ys-y>ytol+1: break
        if not placed: out.append((y,s,e,y))
    return out
