import numpy as np
from ccl import rle_rows

def white_regions(d, x0,x1,y0,y1, minw=3,minh=3,maxw=60,maxh=60, rect=0.75):
    sub=d[y0:y1, x0:x1]
    w=~sub
    runs=rle_rows(w)
    parent={}
    def find(a):
        while parent[a]!=a:
            parent[a]=parent[parent[a]]; a=parent[a]
        return a
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[rb]=ra
    labels=[]; nid=0
    for y in range(w.shape[0]):
        cur=[]
        for (s,e) in runs[y]:
            cur.append((s,e,nid)); parent[nid]=nid; nid+=1
        labels.append(cur)
        if y>0:
            for (s,e,i) in cur:
                for (s2,e2,j) in labels[y-1]:
                    if s2<e and s<e2: union(i,j)
    comps={}
    for y in range(w.shape[0]):
        for (s,e,i) in labels[y]:
            r=find(i)
            if r not in comps: comps[r]=[y,y,s,e,0]
            c=comps[r]; c[0]=min(c[0],y); c[1]=max(c[1],y); c[2]=min(c[2],s); c[3]=max(c[3],e); c[4]+=e-s
    out=[]
    H,W=w.shape
    for r,(cy0,cy1,cx0,cx1,area) in comps.items():
        h=cy1-cy0+1; ww=cx1-cx0+1
        if not(minh<=h<=maxh and minw<=ww<=maxw): continue
        if area/(h*ww) < rect: continue
        if cy0==0 or cx0==0 or cy1==H-1 or cx1==W-1: continue
        out.append((x0+cx0, x0+cx1, y0+cy0, y0+cy1, area/(h*ww)))
    return sorted(out, key=lambda t:(t[2],t[0]))
