import ifcopenshell, numpy as np, math
f=ifcopenshell.open('output/model.ifc')
def mat_from_axis(ax, scale=1.0):
    loc=np.array(ax.Location.Coordinates,float)*scale
    if len(loc)==2: loc=np.array([loc[0],loc[1],0.0])
    def dirv(d,default):
        if d is None: return np.array(default,float)
        v=np.array(d.DirectionRatios,float)
        return v/np.linalg.norm(v)
    z=dirv(ax.Axis,[0,0,1]); x=dirv(ax.RefDirection,[1,0,0])
    x=x-np.dot(x,z)*z; x=x/np.linalg.norm(x)
    y=np.cross(z,x)
    M=np.eye(4); M[:3,0]=x; M[:3,1]=y; M[:3,2]=z; M[:3,3]=loc
    return M
def prod_matrix(p):
    M=np.eye(4)
    chain=[]
    while p is not None and p.is_a('IfcLocalPlacement'):
        chain.append(p.RelativePlacement); p=p.PlacementRelTo
    for ax in reversed(chain):
        # translations are in metres per contract -> convert to mm
        M=M@mat_from_axis(ax,1000.0)
    return M
